import React, { useEffect } from "react";
import { Box, Paper, Typography, Stack } from "@mui/material";
import { motion, useMotionValue, useTransform, animate } from "motion/react";
import { useChartTheme } from "@/hooks/useChartTheme";

const CARD_HEIGHT = 160;

const AnimatedPercent = ({ value, mono }) => {
  const mv = useMotionValue(0);
  const rounded = useTransform(mv, (v) => `${Math.round(v)}%`);

  useEffect(() => {
    const controls = animate(mv, value, { duration: 0.9, ease: "easeOut" });
    return controls.stop;
  }, [value]);

  return <motion.span style={{ color: mono.fg }}>{rounded}</motion.span>;
};

const LinearTrack = ({ percent, mono }) => (
  <Box
    sx={{
      position: "relative",
      width: "100%",
      height: 8,
      borderRadius: 999,
      bgcolor: mono.fade,
      overflow: "hidden",
    }}
  >
    <Box
      component={motion.div}
      initial={{ width: 0 }}
      animate={{ width: `${percent}%` }}
      transition={{ duration: 0.9, ease: "easeOut" }}
      sx={{
        position: "absolute",
        inset: 0,
        borderRadius: 999,
        bgcolor: mono.fg,
      }}
    />
  </Box>
);

const Progress = ({
  label = "Storage used",
  value = 420,
  max = 1000,
  unit = "GB",
}) => {
  const mono = useChartTheme();
  const percent = Math.min(100, Math.round((value / max) * 100));

  return (
    <Paper
      component={motion.div}
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, ease: "easeOut" }}
      elevation={0}
      sx={{
        p: { xs: 2, md: 3 },
        borderRadius: 2,
        border: "1px solid",
        borderColor: mono.border,
        bgcolor: "background.paper",
        width: "100%",
        height: CARD_HEIGHT,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <Stack spacing={1.5} sx={{ width: "100%" }}>
        <Stack direction="row" alignItems="baseline" spacing={1} sx={{ width: "100%" }}>
          <Typography variant="body2" sx={{ fontWeight: 500, color: mono.fg, flexGrow: 1 }}>
            {label}
          </Typography>
          <Typography variant="caption" sx={{ color: mono.axis, flexShrink: 0 }}>
            <AnimatedPercent value={percent} mono={mono} />
          </Typography>
        </Stack>
        <LinearTrack percent={percent} mono={mono} />
        <Typography variant="caption" sx={{ color: mono.axis }}>
          {value.toLocaleString()} / {max.toLocaleString()} {unit}
        </Typography>
      </Stack>
    </Paper>
  );
};

export default Progress;

